select id, $c$carrot_cake$c$, $c$Carrot Cake$c$, $c$كاروت كيك$c$, $c$كيكة بالجزر المبشور والقرفة$c$, $c$Cake made with grated carrot and cinnamon$c$, $c$كيكة طرية معمولة بجزر مبشور وقرفة وساعات عين جمل، والجزر بيخليها مبلولة ومش ناشفة. غالبًا عليها طبقة جبنة كريمي.$c$, $c$A moist cake made with grated carrot, cinnamon and often walnuts; the carrot keeps it soft. Usually topped with cream cheese frosting.$c$, $c${}$c$::jsonb, $c${"kind": "usage", "sections": [{"title_ar": "المكونات", "title_en": "Made with", "lines_ar": ["جزر مبشور، دقيق، سكر، قرفة، زيت، وساعات عين جمل."], "lines_en": ["Grated carrot, flour, sugar, cinnamon, oil and often walnuts."]}, {"title_ar": "الطعم", "title_en": "Taste", "lines_ar": ["حلوة وريحة قرفة، والجزر طعمه مش باين قوي."], "lines_en": ["Sweet and spiced with cinnamon; the carrot barely shows."]}, {"title_ar": "بتتقدم إزاي", "title_en": "How it's served", "lines_ar": ["شريحة تورتة عليها جبنة كريمي."], "lines_en": ["As a slice with cream cheese frosting."]}]}$c$::jsonb, 3
